   149	/**
   150	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   151	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   152	 * (half-even) at every step.
   153	 */
   154	public final class PriceCalculator {
   155	
   156	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   157	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
   158	
   159	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
   160	        int nights = 0;
   161	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   162	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   163	            subtotal = subtotal.add(nightPrice(room, night));
   164	            nights++;
   165	        }
   166	        BigDecimal discount = switch (ratePlan) {
   167	            case STANDARD -> cents(BigDecimal.ZERO);
   168	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
   169	            default -> cents(BigDecimal.ZERO);
   170	        };
   171	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   172	    }
   173	
   174	    /** Calculates price with a generic discount rate. */
   175	    public Price nightlyPrice(Room room, LocalDate checkIn, LocalDate checkOut, BigDecimal discountRate) {
   176	        int nights = 0;
   177	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   178	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   179	            subtotal = subtotal.add(nightPrice(room, night));
   180	            nights++;
   181	        }
   182	        BigDecimal discount = cents(subtotal.multiply(discountRate));
   183	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   184	    }
   185	
   186	    BigDecimal nightPrice(Room room, LocalDate night) {
   187	        BigDecimal nightlyRate = room.nightlyRate();
   188	        if (isHighSeason(night)) {
   189	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   190	        }
   191	        return cents(nightlyRate);
   192	    }
   193	
   194	    /** High season: from December 15 to the end of February, and the whole of July. */
   195	    static boolean isHighSeason(LocalDate date) {
   196	        Month month = date.getMonth();
   197	        return month == Month.JANUARY
   198	                || month == Month.FEBRUARY
   199	                || month == Month.JULY
   200	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   201	    }
   202	
   203	    static BigDecimal cents(BigDecimal value) {
   204	        return value.setScale(2, RoundingMode.HALF_EVEN);
   205	    }
   206	}
